-- Tournament Schedule Manager - protected build
-- local APP_VERSION = 3
local K = {"CcrbrYIO", "kq0iIlfY", "GVu6MBpy"}
local P = ""
local function run(...)
    local key = table.concat(K)
    local seed = 7
    for i = 1, #key do seed = (seed * 31 + key:byte(i)) % 2147483647 end
    if seed == 0 then seed = 1 end
    local prev = 0
    local code = P:gsub("%x%x", function(h)
        seed = (seed * 16807) % 2147483647
        local k = math.floor(seed / 256) % 256
        local c = tonumber(h, 16)
        local p = (c - k - prev) % 256
        prev = c
        return string.char(p)
    end)
    local f, err
    if setfenv then
        f, err = loadstring(code, "=main")
        if f then setfenv(f, getfenv(1)) end
    else
        f, err = load(code, "=main", "t", _ENV)
    end
    if not f then error(err) end
    return f(...)
end
return run(...)
